Method.Source:
static void main(Args _args)
{
    METFTILinesController controller = METFTILinesController::construct();
    controller.parmReportName(ssrsReportStr(METFTILines, Report));
    controller.parmArgs(_args);
    controller.startOperation();
}

/// <summary>
/// constructor
/// </summary>
/// <returns>constructor</returns>
public static METFTILinesController construct()
{
    return new METFTILinesController();
}

/// <summary>
/// Specifies if the batch task is retryable for transient exceptions or not.
/// </summary>
/// <returns>
/// If true is returned, the batch task is retryable, otherwise it is not.
/// </returns>
[Hookable(false)]
final boolean isRetryable() 
{
    return true;
}
